{
  "category_edits": [
    {
      "category": "learning_objective",
      "rationale": "Retain pointwise logistic supervision and add a 0.25-weighted pairwise ranking term over the same sampled pairs and nonpadding positions across all four datasets. This may improve candidate separation while preserving score calibration, sampling, architecture and inference.",
      "edits": [
        {
          "find": "    loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)",
          "replace": "    pointwise_loss = nn.functional.softplus(-pos_scores) + nn.functional.softplus(neg_scores)\n    pairwise_loss = nn.functional.softplus(neg_scores - pos_scores)\n    loss = pointwise_loss + 0.25 * pairwise_loss\n    return (loss * mask).sum() / mask.sum().clamp(min=1.0)"
        }
      ]
    }
  ],
  "change_summary": "Add a 0.25-weighted pairwise ranking objective to the existing logistic loss. Preserve one NextItNet model per category and all other training and predictor behavior."
}
